-- Table: tyre_car_kit
-- Rows exported: 21501

DROP TABLE IF EXISTS `tyre_car_kit`;
CREATE TABLE `tyre_car_kit` (
  `id` int unsigned NOT NULL,
  `model_id` int unsigned NOT NULL,
  `year` smallint unsigned NOT NULL,
  `model_year_id` int unsigned NOT NULL,
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pcd` decimal(6,2) DEFAULT NULL,
  `bolt_count` tinyint unsigned DEFAULT NULL,
  `dia` decimal(6,2) DEFAULT NULL,
  `bolt_size` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_model_year` (`model_id`,`year`),
  KEY `idx_year_row` (`model_year_id`),
  KEY `idx_pcd_bolt` (`bolt_count`,`pcd`),
  KEY `idx_model_year_name` (`model_id`,`year`,`name`),
  KEY `idx_year` (`year`),
  KEY `idx_dia` (`dia`),
  CONSTRAINT `fk_tyre_kit_model` FOREIGN KEY (`model_id`) REFERENCES `tyre_car_model` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tyre_kit_my` FOREIGN KEY (`model_year_id`) REFERENCES `tyre_car_model_year` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

